INSERT INTO `item_sparse_locale` VALUES (165657,'deDE','Das Beste im Leben ist umsonst... und zeitlich begrenzt.','','','','Gratis T-Shirt',69497),(165657,'esES','Las mejores cosas de la vida son gratis. Y temporales.','','','','Camiseta gratis',69497),(165657,'esMX','Las mejores cosas de la vida son gratis. Y temporales.','','','','Camiseta gratuita',69497),(165657,'frFR','Les meilleures choses dans la vie sont gratuites. Et ont une fin.','','','','Chemise gratuite',69497),(165657,'itIT','Le cose migliori della vita sono gratuite. E temporanee.','','','','Camicia Gratuita',69497),(165657,'koKR','세상에 공짜로 주는 것만큼 좋은 게 없지요. 기간 한정이라면 더더욱.','','','','무료 티셔츠',69497),(165657,'ptBR','Tudo que é bom na vida é de graça. E temporário.','','','','Camiseta Grátis',69497),(165657,'ruRU','Все лучшее в жизни – бесплатно. И временно.','','','','Бесплатная футболка',69497),(165657,'zhCN','生命中最美好的东西都是免费的。而且只会风靡一时。','','','','免费T恤',69497),(165657,'zhTW','生命中最珍貴的東西是無價的，也是短暫的。','','','','免費T恤',69497),(167081,'deDE','','','','','Knallgelbes Hemd',69497),(167081,'esES','','','','','Camisa amarilla chillón',69497),(167081,'esMX','','','','','Camisa amarilla audaz',69497),(167081,'frFR','','','','','Chemise jaune soutenu',69497),(167081,'itIT','','','','','Canotta Gialla',69497),(167081,'koKR','','','','','두꺼운 노란색 셔츠',69497),(167081,'ptBR','','','','','Camisa Amarelo-cheguei',69497),(167081,'ruRU','','','','','Крепкая желтая рубашка',69497),(167081,'zhCN','','','','','醒目的黄衬衣',69497),(167081,'zhTW','','','','','醒目的黃襯衣',69497),(167082,'deDE','','','','','Modisches schwarzes Hemd',69497),(167082,'esES','','','','','Camisa negra con estilo',69497),(167082,'esMX','','','','','Camisa negra con estilo',69497),(167082,'frFR','','','','','Chemise noire d’apparat',69497),(167082,'itIT','','','','','Camicia Nera Stilosa',69497),(167082,'koKR','','','','','세련된 검은색 셔츠',69497),(167082,'ptBR','','','','','Camisa Preta Estilosa',69497),(167082,'ruRU','','','','','Стильная черная рубашка',69497),(167082,'zhC